const campana = $('Extraer datos de campana').item.json;
const b = campana.brand;

function driveUrl(url) {
  if (!url || !url.trim()) return '';
  const m = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? `https://drive.google.com/uc?export=download&confirm=t&id=${m[1]}` : url.trim();
}

const prompt = `${b.BRAND_NAME}. Act as a Social Media Art Director and Digital Collage Artist specializing in bold, youth-oriented brand content for Instagram and digital campaigns.
Create a dynamic digital collage featuring ${b.MODEL_DESCRIPTION} drinking a cold ${b.PRODUCT_NAME} with dramatic soda splashes and carbonation effects exploding around the composition.
The model should look ${b.MODEL_ATTITUDE}.
The background should feature ${b.BACKGROUND_STYLE} mixed with abstract street-style collage elements.
Use bold ${b.PRIMARY_COLORS} color blocking inspired by ${b.BRAND_NAME} branding.
Add hand-painted brush strokes, ripped paper textures, graffiti graphics, spray paint effects, bold abstract shapes, layered paper collage effects, dynamic typography, grain, noise texture, and handcrafted imperfections.
The composition should feel ${b.MOOD}.
The model must be positioned ${b.MODEL_POSITION} while ${b.MODEL_ACTION} naturally.
Typography text: "${b.SLOGAN}"
PHASE 1: CONCEPTUAL FRAMEWORK — dynamic digital collage merging fashion photography with graphic design chaos.
PHASE 2: COLOR BLOCKING — Large organic shape 40-60% in bold ${b.PRIMARY_COLORS} behind model.
PHASE 3: GRAPHIC ELEMENTS — 3-5 abstract graphic elements scattered asymmetrically.
PHASE 4: TEXTURE BACKGROUND — off-white textured background blended with ${b.BACKGROUND_STYLE}.
PHASE 5: COMPOSITION — Asymmetric balance, 15-20% negative space, diagonal energy.
TECHNICAL: Aspect Ratio ${b.ASPECT_RATIO}, ${b.RESOLUTION}, sRGB vibrant. Camera: ${b.CAMERA_ANGLE}. Lighting: ${b.LIGHTING_STYLE}. Typography: ${b.TYPOGRAPHY_STYLE}. Energy: ${b.ENERGY_LEVEL}. Audience: ${b.TARGET_AUDIENCE}. Collage: ${b.COLLAGE_INTENSITY}.
First and second attached images: exact face and body reference of the model from different angles — preserve facial identity and body accurately.
Third attached image: exact product reference — preserve label and design accurately.
Fourth attached image: exact logo reference — do not modify logo design.`;

const base = {
  chat_id:       campana.chat_id,
  brand_name:    b.BRAND_NAME,
  prompt_banner: prompt
};

// Emitir hasta 4 items — omitir si el link está vacío
const slots = [
  { img_slot: 'modelo1',   img_url: driveUrl(b.MODEL_IMAGE_DRIVE_LINK) },
  { img_slot: 'modelo2',   img_url: driveUrl(b.MODEL2_IMAGE_DRIVE_LINK || '') },
  { img_slot: 'producto',  img_url: driveUrl(b.PRODUCT_IMAGE_DRIVE_LINK) },
  { img_slot: 'logo',      img_url: driveUrl(b.LOGO_IMAGE_DRIVE_LINK) },
];

return slots
  .filter(s => s.img_url !== '')
  .map(s => ({ json: { ...base, ...s } }));

const b64 = $json.data?.[0]?.b64_json;
