return [{ json: { ok: resp.ok, message_id: resp.result?.message_id } }];

const base = $('Resolver intencion').item.json;
const marcas = $input.all().map(i => i.json).filter(m => m.BRAND_NAME);

const botones = marcas.length
  ? marcas.map(m => [{ text: `🎨 ${m.BRAND_NAME}`, callback_data: `publicar:${m.BRAND_NAME}` }])
  : [[{ text: '(sin marcas configuradas)', callback_data: 'ayuda' }]];

const reply_markup = { inline_keyboard: botones };

const token = $vars.TELEGRAM_BOT_TOKEN;
if (!token) throw new Error('Falta la variable TELEGRAM_BOT_TOKEN en Settings → Variables');

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${token}/sendMessage`,
  body: { chat_id: base.chat_id, text: base.pedir_pregunta, reply_markup },
  json: true
});

return [{ json: { ok: resp.ok, message_id: resp.result?.message_id } }];

const base = $('Resolver intencion').item.json;

// Avatar activo desde config
const configItems = $('Leer avatar activo (off)').all();
const avatar_activo = configItems.find(i => i.json.clave === 'avatar_activo')?.json?.valor || 'sofia_01';

// Instrucciones activas de ESE avatar
const instr = $('Leer instrucciones del avatar').all()
  .map(i => i.json)
  .filter(x => x.activa === 'SI' && x.avatar_id === avatar_activo);

let texto, reply_markup;
if (instr.length === 0) {
  texto = `🔕 El avatar *${avatar_activo}* no tiene instrucciones activas para desactivar.`;
  reply_markup = JSON.stringify({ inline_keyboard: [[{ text: '⬅️ Volver al menú', callback_data: 'ayuda' }]] });
} else {
  texto = `🔕 Instrucciones activas de *${avatar_activo}*. Selecciona la que quieres desactivar:`;
  const botones = instr.map(x => {
    const recorte = String(x.instruccion || '').slice(0, 40);
    return [{ text: `🏷 ${x.tema || '?'}: ${recorte}${x.instruccion.length > 40 ? '…' : ''}`, callback_data: `offsel:${x.id}` }];
  });
  botones.push([{ text: '⬅️ Cancelar', callback_data: 'ayuda' }]);
  reply_markup = JSON.stringify({ inline_keyboard: botones });
}

const token = $vars.TELEGRAM_BOT_TOKEN;
const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${token}/sendMessage`,
  body: { chat_id: base.chat_id, text: texto, reply_markup, parse_mode: 'Markdown' },
  json: true
});

return [{ json: { ok: resp.ok } }];

const base = $('Restaurar contexto comando').item.json;
const instrItems = $input.all().map(i => i.json);
const instr = instrItems.find(x => x.id === base.argumento) || instrItems[0] || {};

const texto = `⚠️ ¿Confirmas desactivar esta instrucción?\n\n` +
  `🏷 Tema: ${instr.tema || '?'}\n` +
  `📝 ${instr.instruccion || '(no encontrada)'}\n\n` +
  `🆔 ${instr.id || base.argumento}`;

